//! What is true of CEF's build per OS: the pins the app downloads and the libraries its host loads from the system.
//! The `// BEGIN` blocks are generated by `gate cef-pin` (see its module doc to re-pin); do not edit them by hand. A
//! new block also needs an arm in `pin`, and an install layout.

use crate::Os;

/// The CEF build the app downloads: where it lives and how to check it.
#[derive(Debug, Clone, PartialEq)]
pub struct Pin {
    pub version: &'static str,
    pub url: &'static str,
    pub size: u64,
    pub sha1: &'static str,
    pub sha256: &'static str,
}

// BEGIN windows64
const PIN_WINDOWS64: Pin = Pin {
    version: "152.0.6+g708dc14+chromium-152.0.7977.83",
    url: "https://cef-builds.spotifycdn.com/cef_binary_152.0.6%2Bg708dc14%2Bchromium-152.0.7977.83_windows64_minimal.tar.bz2",
    size: 171_619_649,
    sha1: "e5e3020627f4528bd43e22f4c4970000b0458e99",
    sha256: "db3e0751979c3cb3068f732ed4f0ef12ade69d183d98ceee120ad08c8d00f74c",
};
// END windows64

// BEGIN linux64
const PIN_LINUX64: Pin = Pin {
    version: "152.0.6+g708dc14+chromium-152.0.7977.83",
    url: "https://cef-builds.spotifycdn.com/cef_binary_152.0.6%2Bg708dc14%2Bchromium-152.0.7977.83_linux64_minimal.tar.bz2",
    size: 321_503_907,
    sha1: "9711b86c105fb590da576fe5a829802f1a79d520",
    sha256: "daf8c2b6e63787d6a91d666205a8a4521419937eabaf47723738c86aea7135bd",
};
// END linux64

/// The CEF build pinned for `os`: `None` where there is none yet.
pub fn pin(os: Os) -> Option<&'static Pin> {
    match os {
        Os::Windows => Some(&PIN_WINDOWS64),
        Os::Linux => Some(&PIN_LINUX64),
        Os::Mac | Os::Other => None,
    }
}

/// Shared libraries the host loads from the system rather than from the runtime.
pub fn system_libs(os: Os) -> &'static [&'static str] {
    match os {
        Os::Linux => &["libnss3.so", "libnspr4.so"],
        Os::Windows | Os::Mac | Os::Other => &[],
    }
}

